}

header {
    background: linear-gradient(135deg, #2c3e50 0%, #3498db 100%);
    color: white;
    padding: 30px;
    text-align: center;
}

header h1 {
    font-size: 2.5rem;
    margin-bottom: 10px;
    font-weight: 300;
}

header p {
    opacity: 0.9;
    font-size: 1.1rem;
}

main {
    padding: 30px;
}

.controls {
    display: grid;
    gap: 20px;
    margin-bottom: 30px;
}

.input-group {
    display: flex;
