    min-height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.result.high {
    background: #e8f6f3;
    border-left-color: #27ae60;
}

.result.medium {
    background: #fef9e7;
    border-left-color: #f39c12;
}

.result.low {
    background: #fdedec;
    border-left-color: #e74c3c;
}

.loading {
    display: inline-block;
    width: 20px;
    height: 20px;
    border: 3px solid #f3f3f3;
    border-top: 3px solid #3498db;
    border-radius: 50%;
    animation: spin 1s linear infinite;
    margin-right: 10px;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

@media (max-width: 600px) {
    .container {
        margin: 10px;
        border-radius: 10px;
    }

    header {
        padding: 20px;
    }

    header h1 {
        font-size: 2rem;
    }

    main {
        padding: 20px;
    }

    .controls {
        gap: 15px;
    }
}
