function createModel(numUsers, numMovies, latentDim = 10) {
    // User input
    const userInput = tf.input({shape: [1], name: 'userInput'});

    // Movie input  
    const movieInput = tf.input({shape: [1], name: 'movieInput'});

    // User embedding
    const userEmbedding = tf.layers.embedding({
        inputDim: numUsers + 1,
        outputDim: latentDim,
        name: 'userEmbedding'
