    baseline: float
    supported: bool
    neighbor_count: int
    max_overlap: int
    weight_sum: float
    adjustment: float
    neighbors: tuple[tuple[int, float, int, int, float, float], ...]


def clip(value: float) -> float:
    return max(1.0, min(5.0, value))


def read_ratings(path: Path) -> list[tuple[int, int, int]]:
    data = []
    seen = set()
    for line_no, line in enumerate(path.read_text(encoding="ascii").splitlines(), 1):
        parts = line.split("\t")
        if len(parts) != 4:
            raise ValueError(f"{path}:{line_no}: expected four tab-separated fields")
        user, item, rating, timestamp = (int(part) for part in parts)
        if user <= 0 or item <= 0 or rating not in (1, 2, 3, 4, 5) or timestamp <= 0:
            raise ValueError(f"{path}:{line_no}: invalid rating record")
        if (user, item) in seen:
            raise ValueError(f"{path}:{line_no}: duplicate user/movie rating")
        seen.add((user, item))
        data.append((user, item, rating))
    if not data:
        raise ValueError(f"{path}: no ratings")
    return data


def read_titles(path: Path | None) -> dict[int, str]:
    if path is None:
        return {}
    titles = {}
    for line_no, line in enumerate(path.read_text(encoding="latin-1").splitlines(), 1):
        parts = line.split("|")
        if len(parts) != 24:
            raise ValueError(f"{path}:{line_no}: expected 24 pipe-separated fields")
        movie_id = int(parts[0])
        if movie_id <= 0 or movie_id in titles:
            raise ValueError(f"{path}:{line_no}: invalid or duplicate movie ID")
        titles[movie_id] = parts[1]
    return titles


def split_ratings(
    ratings: list[tuple[int, int, int]], seed: int = SEED,
    validation_count: int = VAL_COUNT, test_count: int = TEST_COUNT,
) -> tuple[list[tuple[int, int, int]], list[tuple[int, int, int]], list[tuple[int, int, int]]]:
    """Reserve test then validation records while keeping every ID in train.

    This is a warm-start split by construction, not a guarantee that each user
    or movie has enough co-ratings for neighbourhood CF.
    """
    shuffled = ratings.copy()
    random.Random(seed).shuffle(shuffled)
    user_remaining = Counter(user for user, _, _ in ratings)
    item_remaining = Counter(item for _, item, _ in ratings)
    validation = []
    test = []
    train = []
    for row in shuffled:
        user, item, _ = row
        if user_remaining[user] > 1 and item_remaining[item] > 1:
            target = test if len(test) < test_count else validation
            if len(target) < (test_count if target is test else validation_count):
                target.append(row)
                user_remaining[user] -= 1
                item_remaining[item] -= 1
                continue
        train.append(row)
    if len(test) != test_count or len(validation) != validation_count:
        raise ValueError("Could not build requested warm split")
    return train, validation, test


