    const watched = ratings.filter(row => row.userId === userId && row.rating >= 4)
        .sort((a, b) => a.timestamp - b.timestamp || a.movieId - b.movieId)
        .slice(0, 3).map(row => row.movieId);

    // Load the real Week 2 core without triggering its DOM initialization.
    const context = { console, Intl, document: { addEventListener() {} } };
    context.window = context;
    vm.createContext(context);
    for (const filename of ['data.js', 'script.js']) {
        vm.runInContext(fs.readFileSync(path.join(week2, filename), 'utf8'), context);
    }
    const dataset = context.MovieData.createDataset(
        fs.readFileSync(path.join(week2, 'u.item'), 'utf8'),
        fs.readFileSync(path.join(week2, 'u.data'), 'utf8')
    );
    const profile = context.MovieRecommenderCore.buildUserProfile(dataset.movies, watched);
    // Keep the three-film genre profile, while excluding the same complete
    // observed history that both Week 3 lists exclude.
    const equalCandidateProfile = {
        vector: profile.vector,
        watchedMovies: profile.watchedMovies,
        watchedMovieIds: [...model.byUser.get(userId).keys()]
    };
    const week2Top = context.MovieRecommenderCore.rankRecommendations(
        dataset.movies, dataset.ratingSummary, equalCandidateProfile, 5
    );
    const userTop = model.recommendations(userId, 'user');
    const itemTop = model.recommendations(userId, 'item');
    const labels = new Map(dataset.movies.map(movie => [movie.id, movie.title]));
    const ids = list => new Set(list.map(row => row.id || row.movie.id));
    const overlap = (left, right) => [...ids(left)].filter(id => ids(right).has(id)).length;
    process.stdout.write(JSON.stringify({
        userId,
        inputNote: 'Week 2 uses the earliest three >=4 rated movies; Week 3 uses all observed user ratings.',
        candidateNote: 'All three rankings exclude the same complete observed user history.',
        watched: watched.map(id => ({ id, title: labels.get(id) })),
        observedCount: model.byUser.get(userId).size,
        week2: week2Top.map(row => ({ id: row.movie.id, title: row.movie.title,
            cosine: row.similarity })),
        week3User: userTop.map(row => ({ id: row.movie.id, title: labels.get(row.movie.id),
            predictedRating: row.rating, support: row.support })),
        week3Item: itemTop.map(row => ({ id: row.movie.id, title: labels.get(row.movie.id),
            predictedRating: row.rating, support: row.support })),
        overlap: {
            week2User: overlap(week2Top, userTop),
            week2Item: overlap(week2Top, itemTop),
            userItem: overlap(userTop, itemTop)
        }
    }, null, 2) + '\n');
}

main().catch(error => { console.error(error); process.exitCode = 1; });

