"use strict";

const test = require("node:test");
const assert = require("node:assert/strict");
const { readFileSync } = require("node:fs");
const path = require("node:path");
const { performance } = require("node:perf_hooks");

const { parseItemData, parseRatingData } = require("../data.js");
const { CollaborativeFilteringModel } = require("../cf.js");

const root = path.resolve(__dirname, "..");

function near(actual, expected, tolerance = 1e-8) {
    assert.ok(Number.isFinite(actual), `expected a finite number, got ${actual}`);
    assert.ok(Math.abs(actual - expected) <= tolerance,
        `expected ${actual} to be within ${tolerance} of ${expected}`);
}

function movieRow(id, title) {
    return [id, title, ...Array(22).fill("0")].join("|");
}

function handModel(options = {}) {
    // The target is User 1 / Movie D. The three common observations in each
    // relevant pair make both orientations and the n/(n+10) shrinkage visible.
    const movies = ["A", "B", "C", "D"].map((title, index) => ({
        id: index + 1, title, year: null
    }));
    const rows = [
        [1, 1, 5], [1, 2, 4], [1, 3, 1],
        [2, 1, 5], [2, 2, 4], [2, 3, 1], [2, 4, 5],
        [3, 1, 4], [3, 2, 5], [3, 3, 1], [3, 4, 4],
        [4, 1, 1], [4, 2, 2], [4, 3, 5], [4, 4, 1]
    ];
    return new CollaborativeFilteringModel(movies,
        rows.map(([userId, movieId, rating]) => ({ userId, movieId, rating })),
        options);
}

test("exported MovieLens parsers preserve IDs and reject malformed or duplicate records", () => {
    const films = parseItemData(`${movieRow(7, "Film (1997)")}\n${movieRow(3, "Other")}\n`);
    assert.deepEqual(films.map(({ id, title, year }) => ({ id, title, year })), [
        { id: 7, title: "Film", year: 1997 },
        { id: 3, title: "Other", year: null }
    ]);
    assert.deepEqual(parseRatingData("42\t7\t5\t123\n"), [
        { userId: 42, movieId: 7, rating: 5, timestamp: 123 }
    ]);
    assert.throws(() => parseItemData("7|too few fields"), /expected 24 fields/);
    assert.throws(() => parseItemData(`${movieRow(7, "A")}\n${movieRow(7, "B")}`),
        /duplicate movie/);
    assert.throws(() => parseRatingData("1\t2\t0\t123"), /invalid or duplicate rating/);
    assert.throws(() => parseRatingData("1\t2\t5\t123\n1\t2\t4\t124"),
        /duplicate rating/);
});

test("hand-calculated user and item similarities match centred, overlap-weighted cosine", async () => {
    const model = handModel();
    await model.prepareItemSimilarities();

    near(model.globalMean, 3.2);
    near(model.baseline(1, 4), 3.2615384615384615);
    near(model.userSimilarity(1, 2).score, 0.2241327258722103);
    near(model.userSimilarity(1, 3).score, 0.20316758139313745);
    near(model.userSimilarity(1, 4).score, -0.2241327258722103);
    near(model.itemSimilarity(4, 1).score, 3 / 13);
    near(model.itemSimilarity(4, 2).score, 0.11207581482858063);
    near(model.itemSimilarity(4, 3).score, -0.22075539284417395);
    assert.equal(model.userSimilarity(1, 2).overlap, 3);
    assert.equal(model.itemSimilarity(4, 1).overlap, 3);
    near(model.itemSimilarity(1, 4).score, model.itemSimilarity(4, 1).score);

    const user = model.predictUser(1, 4);
    const item = model.predictItem(1, 4);
    near(user.rating, 3.8009430589071114);
    near(item.rating, 3.7843160956958264);
    assert.equal(user.support, 2); // Negative User 4 similarity is excluded.
    assert.equal(item.support, 2); // Negative Movie C similarity is excluded.
    assert.equal(user.fallback, false);
    assert.equal(item.fallback, false);

    // With aggregate correction shrinkage disabled, the same hand calculation
    // reduces to the textbook weighted-residual formula.
    const unshrunk = handModel({ minContributors: 1, adjustmentShrinkage: 0 });
    await unshrunk.prepareItemSimilarities();
    near(unshrunk.predictUser(1, 4).rating, 4.432120462944978);
    near(unshrunk.predictItem(1, 4).rating, 4.546727046167357);
});

test("overlap threshold, one contributor, and zero norms force an honest fallback", async () => {
    const insufficient = handModel({ minOverlap: 4 });
    await insufficient.prepareItemSimilarities();
    assert.deepEqual(insufficient.userSimilarity(1, 2), { score: 0, overlap: 3 });
    assert.deepEqual(insufficient.itemSimilarity(4, 1), { score: 0, overlap: 3 });
    for (const prediction of [insufficient.predictUser(1, 4), insufficient.predictItem(1, 4)]) {
        near(prediction.rating, insufficient.baseline(1, 4));
        assert.equal(prediction.support, 0);
        assert.equal(prediction.fallback, true);
    }

    const oneNeighbor = handModel({ neighbors: 1 });
    await oneNeighbor.prepareItemSimilarities();
    for (const prediction of [oneNeighbor.predictUser(1, 4), oneNeighbor.predictItem(1, 4)]) {
        near(prediction.rating, oneNeighbor.baseline(1, 4));
        assert.equal(prediction.support, 1);
        assert.equal(prediction.fallback, true);
    }

    const movies = [1, 2, 3, 4].map(id => ({ id, title: `M${id}` }));
    const ratings = [
        ...[1, 2, 3].map(movieId => ({ userId: 1, movieId, rating: 3 })),
        ...[2, 3, 4].flatMap(userId => [1, 2, 3, 4].map(movieId => ({
            userId, movieId, rating: 3
        })))
    ];
    const flat = new CollaborativeFilteringModel(movies, ratings);
    await flat.prepareItemSimilarities();
    assert.deepEqual(flat.userSimilarity(1, 2), { score: 0, overlap: 3 });
    assert.deepEqual(flat.itemSimilarity(4, 1), { score: 0, overlap: 3 });
    for (const prediction of [flat.predictUser(1, 4), flat.predictItem(1, 4)]) {
        near(prediction.rating, 3);
        assert.equal(prediction.fallback, true);
    }
});

test("cold users and movies use the appropriate smoothed baseline", async () => {
    const model = handModel();
    await model.prepareItemSimilarities();
    for (const predict of [model.predictUser.bind(model), model.predictItem.bind(model)]) {
        const newUser = predict(99, 4);
        const newMovie = predict(1, 99);
        const bothNew = predict(99, 99);
        for (const result of [newUser, newMovie, bothNew]) {
            assert.equal(result.fallback, true);
            assert.equal(result.support, 0);
        }
        near(newUser.rating, model.baseline(99, 4));
        near(newMovie.rating, model.baseline(1, 99));
        near(bothNew.rating, model.globalMean);
    }
});

test("known ratings cannot be predicted or recommended; tied Top-5 is stable", async () => {
    const model = handModel();
    await model.prepareItemSimilarities();
    assert.throws(() => model.predictUser(1, 1), /already rated/);
    assert.throws(() => model.predictItem(1, 1), /already rated/);
    assert.deepEqual(model.recommendations(1, "user").map(row => row.movie.id), [4]);
    assert.deepEqual(model.recommendations(1, "item").map(row => row.movie.id), [4]);

    const movies = [6, 4, 2, 5, 1, 3].map(id => ({ id, title: `M${id}` }));
    const ratings = [{ userId: 1, movieId: 1, rating: 3 }];
    const ties = new CollaborativeFilteringModel(movies, ratings);
    await ties.prepareItemSimilarities();
    for (const method of ["user", "item"]) {
        const first = ties.recommendations(1, method);
        assert.deepEqual(first.map(row => row.movie.id), [2, 3, 4, 5, 6]);
        assert.ok(first.every(row => row.fallback && row.support === 0));
        assert.deepEqual(ties.recommendations(1, method), first);
    }
});

test("complete MovieLens files produce bounded, unseen Top-5s with usable latency", async t => {
    const movies = parseItemData(readFileSync(path.join(root, "u.item"), "utf8"));
    const ratings = parseRatingData(readFileSync(path.join(root, "u.data"), "utf8"));
    assert.equal(movies.length, 1682);
    assert.equal(ratings.length, 100000);
    assert.equal(new Set(ratings.map(row => row.userId)).size, 943);
    assert.equal(movies.find(movie => movie.id === 543).title, "Misérables, Les");

    const model = new CollaborativeFilteringModel(movies, ratings);
    assert.equal(model.byUser.get(405).size, 737);
    const preparationStart = performance.now();
    await model.prepareItemSimilarities();
    const preparationMs = performance.now() - preparationStart;
    assert.ok(preparationMs < 30000, `item preparation took ${preparationMs.toFixed(0)} ms`);
    t.diagnostic(`item similarity preparation: ${preparationMs.toFixed(0)} ms`);

    for (const userId of [1, 405]) {
        for (const method of ["user", "item"]) {
            const start = performance.now();
            const rows = model.recommendations(userId, method);
            const elapsedMs = performance.now() - start;
            assert.ok(elapsedMs < 10000,
                `User ${userId} ${method} Top-5 took ${elapsedMs.toFixed(0)} ms`);
            assert.equal(rows.length, 5);
            assert.equal(new Set(rows.map(row => row.movie.id)).size, 5);
            for (const row of rows) {
                assert.equal(model.byUser.get(userId).has(row.movie.id), false);
                assert.ok(Number.isFinite(row.rating) && row.rating >= 1 && row.rating <= 5);
            }
            assert.ok(rows.some(row => !row.fallback));
            assert.deepEqual(model.recommendations(userId, method), rows);
            t.diagnostic(`User ${userId} ${method} Top-5: ${elapsedMs.toFixed(0)} ms`);
        }
    }
});

